    let mut args = serde_json::json!({});
    if let Some(ns) = ns {
        args["ns"] = ns.into();
    }
    if let Some(b) = budget {
        args["budget"] = b.into();
    }
    let text = leviathan::http::call_tool(url, token.as_deref(), "recall", &args)?;
    Ok(if text.contains("0 of 0 current") { EMPTY.to_string() } else { text })
}

